-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Calculates collection and money objectives from live bags, cached bank contents and vendor values.
-- Valuation is read-only; inventory-changing actions belong to RouteActions.

local L = LibStub("AceLocale-3.0"):GetLocale("APR")

-- Bank counts are character data, independent of the active route. Refresh them
-- only while the bank is accessible; they remain available after closing/reloading.
function APR:SaveBankItemCounts()
    if not self.routeBankOpen or not APRData or not APRData[self.PlayerID] then return end
    local slots = C_Container and C_Container.GetContainerNumSlots or GetContainerNumSlots
    local info = C_Container and C_Container.GetContainerItemInfo or GetContainerItemInfo
    if not slots or not info or (slots(-1) or 0) == 0 then return end
    local counts = {}
    local bags = {-1}
    for bag = (NUM_BAG_SLOTS or 4) + 1, (NUM_BAG_SLOTS or 4) + (NUM_BANKBAGSLOTS or 7) do bags[#bags + 1] = bag end
    for _, bag in ipairs(bags) do
        for slot = 1, slots(bag) or 0 do
            local item, count, _, _, _, _, _, _, _, id = info(bag, slot)
            if type(item) == "table" then id, count = item.itemID, item.stackCount end
            if id then counts[id] = (counts[id] or 0) + (count or 0) end
        end
    end
    APRData[self.PlayerID].BankItems = counts
end--[[APR_DIAG]]; APR.SaveBankItemCounts = APRTrace("APR-Core/utils/LootUtils.lua:13:APR:SaveBankItemCounts#1", APR.SaveBankItemCounts)--[[/APR_DIAG]]

function APR:GetCollectionItemCount(itemID, includeBank)
    local fn = C_Item and C_Item.GetItemCount or GetItemCount
    if not fn then return 0 end
    local bags = fn(itemID, false) or 0
    if includeBank == false then return bags end
    local data = APRData and APRData[self.PlayerID]
    if data and data.BankItems then return bags + (data.BankItems[itemID] or 0) end
    return fn(itemID, true) or bags
end--[[APR_DIAG]]; APR.GetCollectionItemCount = APRTrace("APR-Core/utils/LootUtils.lua:31:APR:GetCollectionItemCount#2", APR.GetCollectionItemCount)--[[/APR_DIAG]]

function APR:GetCollectionRequiredQuantity(rule)
    if rule.quantityFromSkill then
        local target = rule.quantityFromSkill
        local remaining = math.max(0, target.rank - self:GetRouteSkill(target))
        return math.min(rule.quantity or target.rank, remaining)
    end
    return math.max(rule.quantity or 1, 1)
end--[[APR_DIAG]]; APR.GetCollectionRequiredQuantity = APRTrace("APR-Core/utils/LootUtils.lua:41:APR:GetCollectionRequiredQuantity#3", APR.GetCollectionRequiredQuantity)--[[/APR_DIAG]]

function APR:IsRouteCollectionComplete(rule)
    return self:GetCollectionItemCount(rule.itemID, rule.includeBank) >= self:GetCollectionRequiredQuantity(rule)
end--[[APR_DIAG]]; APR.IsRouteCollectionComplete = APRTrace("APR-Core/utils/LootUtils.lua:50:APR:IsRouteCollectionComplete#4", APR.IsRouteCollectionComplete)--[[/APR_DIAG]]

-- Current cash plus the theoretical vendor value of carried items. Never counts
-- bank contents, buys back items, or sells anything. Missing item data contributes
-- zero until GET_ITEM_INFO_RECEIVED refreshes the active objective.
function APR:GetLootMoneyProgress(rule)
    local cash, resale = GetMoney() or 0, 0
    local itemInfo = C_Item and C_Item.GetItemInfo or GetItemInfo
    -- Stacks can share a link/ID. Fetch each exact variant once per estimate;
    -- keep this local so newly loaded prices are visible on the next refresh.
    local prices = {}
    local function addItem(item, count)
        if not item or not itemInfo then return end
        local price = prices[item]
        if price == nil then
            price = select(11, itemInfo(item))
            prices[item] = type(price) == "number" and price or false
        end
        if type(price) == "number" and price > 0 then
            resale = resale + price * (count or 1)
        end
    end--[[APR_DIAG]]; addItem = APRTrace("APR-Core/utils/LootUtils.lua:63:addItem#6", addItem)--[[/APR_DIAG]]
    local saleItems = {}
    if rule.junkOnly then
        for _, slot in ipairs(rule.equippedSlots or {}) do
            local id = GetInventoryItemID and GetInventoryItemID("player", slot)
            if id then saleItems[id] = true end
        end
        -- Keep the same listed weapon eligible after manual unequip, until sale.
        local state = self.routeActionState
        local current = APRData and APRData[self.PlayerID] and APRData[self.PlayerID][self.ActiveRoute]
        if state and current and state.token == self:GetCurrentStepToken(self.ActiveRoute, current) then
            for slot, id in pairs(state.equippedItemsBySlot or {}) do
                for _, selected in ipairs(rule.equippedSlots or {}) do
                    if selected == slot then saleItems[id] = true end
                end
            end
        end
    end
    local slots = C_Container and C_Container.GetContainerNumSlots or GetContainerNumSlots
    local info = C_Container and C_Container.GetContainerItemInfo or GetContainerItemInfo
    if slots and info then
        for bag = 0, NUM_TOTAL_EQUIPPED_BAG_SLOTS or NUM_BAG_SLOTS or 4 do
            for slot = 1, slots(bag) or 0 do
                local item, count, _, quality, _, _, link, _, noValue, id = info(bag, slot)
                if type(item) == "table" then
                    link, id, count, noValue, quality = item.hyperlink, item.itemID, item.stackCount, item.hasNoValue, item.quality
                end
                if not noValue and (not rule.junkOnly or quality == 0 or saleItems[id]) then
                    addItem(link or id, count)
                end
            end
        end
    end
    if GetInventoryItemLink or GetInventoryItemID then
        local selected = {}
        if rule.includeEquipped then
            for slot = 1, 19 do selected[slot] = true end
        else
            for _, slot in ipairs(rule.equippedSlots or {}) do selected[slot] = true end
        end
        for slot in pairs(selected) do
            local item = GetInventoryItemLink and GetInventoryItemLink("player", slot)
                or GetInventoryItemID and GetInventoryItemID("player", slot)
            addItem(item, GetInventoryItemCount and GetInventoryItemCount("player", slot) or 1)
        end
    end
    return cash, resale, math.max(1, tonumber(rule.copper) or 1)
end--[[APR_DIAG]]; APR.GetLootMoneyProgress = APRTrace("APR-Core/utils/LootUtils.lua:57:APR:GetLootMoneyProgress#5", APR.GetLootMoneyProgress)--[[/APR_DIAG]]

-- Eligibility filter using the same cash/resale estimate as the loot objective.
function APR:MeetsVendorMoney(rule)
    local cash, resale = self:GetLootMoneyProgress(rule)
    return self:CompareRouteNumber(cash + resale, rule.operator or ">=", rule.copper)
end--[[APR_DIAG]]; APR.MeetsVendorMoney = APRTrace("APR-Core/utils/LootUtils.lua:123:APR:MeetsVendorMoney#7", APR.MeetsVendorMoney)--[[/APR_DIAG]]

function APR:FormatLootMoney(copper)
    local formatMoney = C_CurrencyInfo and C_CurrencyInfo.GetCoinTextureString or GetCoinTextureString
    return formatMoney and formatMoney(copper) or tostring(copper)
end--[[APR_DIAG]]; APR.FormatLootMoney = APRTrace("APR-Core/utils/LootUtils.lua:128:APR:FormatLootMoney#8", APR.FormatLootMoney)--[[/APR_DIAG]]

function APR:GetLootMoneyStepText(rule)
    return string.format(L["LOOT_MONEY"], self:FormatLootMoney(rule.copper))
end--[[APR_DIAG]]; APR.GetLootMoneyStepText = APRTrace("APR-Core/utils/LootUtils.lua:133:APR:GetLootMoneyStepText#9", APR.GetLootMoneyStepText)--[[/APR_DIAG]]
